  T('simple-interest', 'Simple Interest Calculator', 'Financial', 'simple interest calculator', 'Calculate simple interest and total amount.', { inputs: [{ k: 'p', label: 'Principal', v: 100000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 8, step: 'any' }, { k: 't', label: 'Time (years)', v: 5, step: 'any' }], calc: function (v) { var i = v.p * v.r * v.t / 100; return [['Interest', fmoney(i)], ['Total amount', fmoney(v.p + i)]]; } });
  T('compound-interest', 'Compound Interest Calculator', 'Financial', 'compound interest calculator', 'Calculate compound interest with flexible compounding.', { inputs: [{ k: 'p', label: 'Principal', v: 100000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 8, step: 'any' }, { k: 't', label: 'Time (years)', v: 5, step: 'any' }, { k: 'n', label: 'Compounds / year', t: 'sel', v: '12', opts: [opt('1', 'Yearly'), opt('2', 'Half-yearly'), opt('4', 'Quarterly'), opt('12', 'Monthly'), opt('365', 'Daily')] }], calc: function (v) { var n = parseFloat(v.n); var a = v.p * Math.pow(1 + v.r / 100 / n, n * v.t); return [['Maturity', fmoney(a)], ['Interest', fmoney(a - v.p)]]; } });
  T('apr', 'APR Calculator', 'Financial', 'apr calculator, annual percentage rate', 'Estimate the APR on a loan including fees.', { inputs: [{ k: 'amt', label: 'Loan amount', v: 200000, step: 'any' }, { k: 'fee', label: 'Fees', v: 5000, step: 'any' }, { k: 'r', label: 'Interest rate (%)', v: 10, step: 'any' }, { k: 't', label: 'Term (years)', v: 5, step: 'any' }], calc: function (v) { var interest = v.amt * v.r / 100 * v.t; var apr = (interest + v.fee) / v.amt / v.t * 100; return [['Approx APR', fnum(apr, 3) + ' %'], ['Total cost', fmoney(interest + v.fee)]]; } });
  T('apy', 'APY Calculator', 'Financial', 'apy calculator, annual percentage yield', 'Calculate annual percentage yield from a nominal rate.', { inputs: [{ k: 'r', label: 'Nominal rate (%)', v: 8, step: 'any' }, { k: 'n', label: 'Compounds / year', v: 12, step: '1' }], calc: function (v) { return [['APY', fnum((Math.pow(1 + v.r / 100 / v.n, v.n) - 1) * 100, 4) + ' %']]; } });
  T('down-payment', 'Down Payment Calculator', 'Financial', 'down payment calculator', 'Calculate the down payment and loan amount for a purchase.', { inputs: [{ k: 'price', label: 'Price', v: 5000000, step: 'any' }, { k: 'p', label: 'Down payment (%)', v: 20, step: 'any' }], calc: function (v) { var d = v.price * v.p / 100; return [['Down payment', fmoney(d)], ['Loan amount', fmoney(v.price - d)]]; } });
  T('car-loan', 'Car Loan Calculator', 'Financial', 'car loan calculator, auto loan emi', 'Calculate monthly payment for a car loan.', { inputs: [{ k: 'p', label: 'Loan amount', v: 800000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 9.5, step: 'any' }, { k: 't', label: 'Term (years)', v: 5, step: 'any' }], calc: function (v) { var m = v.r / 1200, n = v.t * 12; var emi = m ? v.p * m * Math.pow(1 + m, n) / (Math.pow(1 + m, n) - 1) : v.p / n; return [['Monthly payment', fmoney(emi)], ['Total interest', fmoney(emi * n - v.p)], ['Total paid', fmoney(emi * n)]]; } });
  T('home-loan', 'Home Loan Calculator', 'Financial', 'home loan calculator, housing loan emi', 'Calculate monthly EMI for a home loan.', { inputs: [{ k: 'p', label: 'Loan amount', v: 5000000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 8.5, step: 'any' }, { k: 't', label: 'Term (years)', v: 20, step: 'any' }], calc: function (v) { var m = v.r / 1200, n = v.t * 12; var emi = m ? v.p * m * Math.pow(1 + m, n) / (Math.pow(1 + m, n) - 1) : v.p / n; return [['Monthly EMI', fmoney(emi)], ['Total interest', fmoney(emi * n - v.p)], ['Total paid', fmoney(emi * n)]]; } });
  T('personal-loan', 'Personal Loan Calculator', 'Financial', 'personal loan calculator, emi', 'Calculate EMI and interest for a personal loan.', { inputs: [{ k: 'p', label: 'Loan amount', v: 300000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 14, step: 'any' }, { k: 't', label: 'Term (months)', v: 24, step: 'any' }], calc: function (v) { var m = v.r / 1200, n = v.t; var emi = m ? v.p * m * Math.pow(1 + m, n) / (Math.pow(1 + m, n) - 1) : v.p / n; return [['Monthly EMI', fmoney(emi)], ['Total interest', fmoney(emi * n - v.p)]]; } });
  T('loan-eligibility', 'Loan Eligibility Calculator', 'Financial', 'loan eligibility calculator', 'Estimate how much loan you qualify for based on income.', { inputs: [{ k: 'income', label: 'Monthly income', v: 80000, step: 'any' }, { k: 'foir', label: 'EMI capacity (% of income)', v: 50, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 9, step: 'any' }, { k: 't', label: 'Term (years)', v: 20, step: 'any' }], calc: function (v) { var emi = v.income * v.foir / 100, m = v.r / 1200, n = v.t * 12; var p = m ? emi * (Math.pow(1 + m, n) - 1) / (m * Math.pow(1 + m, n)) : emi * n; return [['Eligible loan', fmoney(p)], ['Affordable EMI', fmoney(emi)]]; } });
  T('balloon-loan', 'Balloon Loan Calculator', 'Financial', 'balloon loan calculator', 'Calculate payments for a loan with a final balloon amount.', { inputs: [{ k: 'p', label: 'Loan amount', v: 1000000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 9, step: 'any' }, { k: 't', label: 'Term (years)', v: 5, step: 'any' }, { k: 'b', label: 'Balloon amount', v: 300000, step: 'any' }], calc: function (v) { var m = v.r / 1200, n = v.t * 12; var pv = v.b / Math.pow(1 + m, n); var emi = m ? (v.p - pv) * m * Math.pow(1 + m, n) / (Math.pow(1 + m, n) - 1) : (v.p - v.b) / n; return [['Monthly payment', fmoney(emi)], ['Balloon due', fmoney(v.b)]]; } });
  T('credit-card-payoff', 'Credit Card Payoff Calculator', 'Financial', 'credit card payoff calculator', 'Find how long it takes to clear a credit-card balance.', { inputs: [{ k: 'bal', label: 'Balance', v: 100000, step: 'any' }, { k: 'r', label: 'APR (%)', v: 36, step: 'any' }, { k: 'pay', label: 'Monthly payment', v: 5000, step: 'any' }], calc: function (v) { var m = v.r / 1200, b = v.bal, mo = 0, tot = 0; while (b > 0 && mo < 600) { b += b * m; b -= v.pay; tot += v.pay; mo++; } return [['Months to clear', mo >= 600 ? 'Payment too low' : mo], ['Total paid', fmoney(Math.min(tot, tot))]]; } });
  T('debt-to-income', 'Debt-to-Income Ratio Calculator', 'Financial', 'debt to income ratio calculator, dti', 'Calculate your debt-to-income (DTI) ratio.', { inputs: [{ k: 'debt', label: 'Monthly debt payments', v: 25000, step: 'any' }, { k: 'income', label: 'Gross monthly income', v: 100000, step: 'any' }], calc: function (v) { return [['DTI ratio', fnum(v.debt / v.income * 100, 2) + ' %'], ['Status', v.debt / v.income <= 0.36 ? 'Healthy' : 'High']]; } });
  T('savings-interest', 'Savings Account Calculator', 'Financial', 'savings account interest calculator', 'Project savings with regular monthly deposits.', { inputs: [{ k: 'init', label: 'Initial deposit', v: 50000, step: 'any' }, { k: 'mon', label: 'Monthly deposit', v: 5000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 6, step: 'any' }, { k: 't', label: 'Years', v: 10, step: 'any' }], calc: function (v) { var m = v.r / 1200, n = v.t * 12; var fv = v.init * Math.pow(1 + m, n) + (m ? v.mon * (Math.pow(1 + m, n) - 1) / m : v.mon * n); return [['Maturity', fmoney(fv)], ['Invested', fmoney(v.init + v.mon * n)], ['Interest', fmoney(fv - v.init - v.mon * n)]]; } });
  T('lumpsum', 'Lumpsum Investment Calculator', 'Financial', 'lumpsum calculator, mutual fund', 'Project growth of a one-time lumpsum investment.', { inputs: [{ k: 'p', label: 'Investment', v: 100000, step: 'any' }, { k: 'r', label: 'Return (% p.a.)', v: 12, step: 'any' }, { k: 't', label: 'Years', v: 10, step: 'any' }], calc: function (v) { var fv = v.p * Math.pow(1 + v.r / 100, v.t); return [['Future value', fmoney(fv)], ['Gain', fmoney(fv - v.p)]]; } });
  T('swp', 'SWP Calculator', 'Financial', 'swp calculator, systematic withdrawal plan', 'Calculate balance under a systematic withdrawal plan.', { inputs: [{ k: 'p', label: 'Investment', v: 1000000, step: 'any' }, { k: 'w', label: 'Monthly withdrawal', v: 10000, step: 'any' }, { k: 'r', label: 'Return (% p.a.)', v: 8, step: 'any' }, { k: 't', label: 'Years', v: 10, step: 'any' }], calc: function (v) { var m = v.r / 1200, n = v.t * 12, b = v.p; for (var i = 0; i < n; i++) { b += b * m; b -= v.w; } return [['Balance left', fmoney(Math.max(b, 0))], ['Total withdrawn', fmoney(v.w * n)]]; } });
  T('stp', 'STP Calculator', 'Financial', 'stp calculator, systematic transfer plan', 'Estimate corpus value of a systematic transfer plan.', { inputs: [{ k: 'p', label: 'Source amount', v: 600000, step: 'any' }, { k: 'tr', label: 'Monthly transfer', v: 50000, step: 'any' }, { k: 'r', label: 'Target return (% p.a.)', v: 12, step: 'any' }], calc: function (v) { var months = Math.floor(v.p / v.tr), m = v.r / 1200; var fv = m ? v.tr * (Math.pow(1 + m, months) - 1) / m : v.tr * months; return [['Transfers', months + ' months'], ['Estimated value', fmoney(fv)]]; } });
  T('dividend-yield', 'Dividend Yield Calculator', 'Financial', 'dividend yield calculator', 'Calculate the dividend yield of a stock.', { inputs: [{ k: 'div', label: 'Annual dividend / share', v: 20, step: 'any' }, { k: 'price', label: 'Share price', v: 500, step: 'any' }], calc: function (v) { return [['Dividend yield', fnum(v.div / v.price * 100, 3) + ' %']]; } });
  T('dividend-income', 'Dividend Income Calculator', 'Financial', 'dividend income calculator', 'Calculate total dividend income from your holdings.', { inputs: [{ k: 'sh', label: 'Shares held', v: 1000, step: 'any' }, { k: 'div', label: 'Dividend / share', v: 15, step: 'any' }], calc: function (v) { return [['Annual income', fmoney(v.sh * v.div)], ['Monthly avg', fmoney(v.sh * v.div / 12)]]; } });
  T('stock-return', 'Stock Return Calculator', 'Financial', 'stock return calculator, profit', 'Calculate profit and return percentage on a stock trade.', { inputs: [{ k: 'buy', label: 'Buy price', v: 100, step: 'any' }, { k: 'sell', label: 'Sell price', v: 130, step: 'any' }, { k: 'qty', label: 'Quantity', v: 100, step: 'any' }], calc: function (v) { var p = (v.sell - v.buy) * v.qty; return [['Profit/Loss', fmoney(p)], ['Return', fnum((v.sell - v.buy) / v.buy * 100, 2) + ' %']]; } });
  T('break-even', 'Break-Even Point Calculator', 'Business', 'break even calculator, units', 'Find the break-even number of units to sell.', { inputs: [{ k: 'fc', label: 'Fixed costs', v: 100000, step: 'any' }, { k: 'price', label: 'Price per unit', v: 500, step: 'any' }, { k: 'vc', label: 'Variable cost per unit', v: 300, step: 'any' }], calc: function (v) { var u = v.fc / (v.price - v.vc); return [['Break-even units', fnum(u, 0)], ['Break-even revenue', fmoney(u * v.price)]]; } });
  T('roas', 'ROAS Calculator', 'Business', 'roas calculator, return on ad spend', 'Calculate return on ad spend (ROAS).', { inputs: [{ k: 'rev', label: 'Revenue from ads', v: 500000, step: 'any' }, { k: 'spend', label: 'Ad spend', v: 100000, step: 'any' }], calc: function (v) { return [['ROAS', fnum(v.rev / v.spend, 2) + 'x'], ['As %', fnum(v.rev / v.spend * 100, 1) + ' %']]; } });
  T('cpc', 'CPC Calculator', 'Business', 'cpc calculator, cost per click', 'Calculate cost per click for an ad campaign.', { inputs: [{ k: 'cost', label: 'Total cost', v: 50000, step: 'any' }, { k: 'clicks', label: 'Clicks', v: 10000, step: 'any' }], calc: function (v) { return [['CPC', fmoney(v.cost / v.clicks)]]; } });
  T('cpm', 'CPM Calculator', 'Business', 'cpm calculator, cost per mille', 'Calculate cost per thousand impressions (CPM).', { inputs: [{ k: 'cost', label: 'Total cost', v: 50000, step: 'any' }, { k: 'imp', label: 'Impressions', v: 1000000, step: 'any' }], calc: function (v) { return [['CPM', fmoney(v.cost / v.imp * 1000)]]; } });
  T('ctr', 'CTR Calculator', 'Business', 'ctr calculator, click through rate', 'Calculate click-through rate (CTR).', { inputs: [{ k: 'clicks', label: 'Clicks', v: 1200, step: 'any' }, { k: 'imp', label: 'Impressions', v: 80000, step: 'any' }], calc: function (v) { return [['CTR', fnum(v.clicks / v.imp * 100, 3) + ' %']]; } });
  T('conversion-rate', 'Conversion Rate Calculator', 'Business', 'conversion rate calculator', 'Calculate conversion rate from visitors and conversions.', { inputs: [{ k: 'conv', label: 'Conversions', v: 250, step: 'any' }, { k: 'visits', label: 'Visitors', v: 10000, step: 'any' }], calc: function (v) { return [['Conversion rate', fnum(v.conv / v.visits * 100, 3) + ' %']]; } });
  T('customer-ltv', 'Customer Lifetime Value Calculator', 'Business', 'clv calculator, customer lifetime value', 'Estimate customer lifetime value (CLV).', { inputs: [{ k: 'avg', label: 'Avg purchase value', v: 2000, step: 'any' }, { k: 'freq', label: 'Purchases / year', v: 6, step: 'any' }, { k: 'years', label: 'Customer lifespan (years)', v: 4, step: 'any' }], calc: function (v) { return [['Lifetime value', fmoney(v.avg * v.freq * v.years)], ['Annual value', fmoney(v.avg * v.freq)]]; } });
  T('cac', 'Customer Acquisition Cost Calculator', 'Business', 'cac calculator, acquisition cost', 'Calculate customer acquisition cost (CAC).', { inputs: [{ k: 'spend', label: 'Sales + marketing spend', v: 500000, step: 'any' }, { k: 'cust', label: 'New customers', v: 250, step: 'any' }], calc: function (v) { return [['CAC', fmoney(v.spend / v.cust)]]; } });
  T('payback-period', 'Payback Period Calculator', 'Business', 'payback period calculator', 'Calculate the payback period of an investment.', { inputs: [{ k: 'inv', label: 'Initial investment', v: 1000000, step: 'any' }, { k: 'cf', label: 'Annual cash flow', v: 250000, step: 'any' }], calc: function (v) { return [['Payback period', fnum(v.inv / v.cf, 2) + ' years']]; } });
  T('npv', 'NPV Calculator', 'Business', 'npv calculator, net present value', 'Calculate net present value of equal annual cash flows.', { inputs: [{ k: 'inv', label: 'Initial investment', v: 1000000, step: 'any' }, { k: 'cf', label: 'Annual cash flow', v: 300000, step: 'any' }, { k: 'r', label: 'Discount rate (%)', v: 10, step: 'any' }, { k: 'n', label: 'Years', v: 5, step: 'any' }], calc: function (v) { var npv = -v.inv, r = v.r / 100; for (var i = 1; i <= v.n; i++) npv += v.cf / Math.pow(1 + r, i); return [['NPV', fmoney(npv)], ['Decision', npv >= 0 ? 'Accept' : 'Reject']]; } });
  T('roi-period', 'Annualized ROI Calculator', 'Business', 'annualized roi calculator', 'Calculate annualized return on investment.', { inputs: [{ k: 'init', label: 'Initial value', v: 100000, step: 'any' }, { k: 'final', label: 'Final value', v: 180000, step: 'any' }, { k: 't', label: 'Years', v: 3, step: 'any' }], calc: function (v) { var total = (v.final - v.init) / v.init * 100; var ann = (Math.pow(v.final / v.init, 1 / v.t) - 1) * 100; return [['Total ROI', fnum(total, 2) + ' %'], ['Annualized ROI', fnum(ann, 2) + ' %']]; } });
  T('depreciation', 'Depreciation Calculator', 'Business', 'depreciation calculator, straight line', 'Calculate straight-line depreciation of an asset.', { inputs: [{ k: 'cost', label: 'Asset cost', v: 500000, step: 'any' }, { k: 'salvage', label: 'Salvage value', v: 50000, step: 'any' }, { k: 'life', label: 'Useful life (years)', v: 5, step: 'any' }], calc: function (v) { var d = (v.cost - v.salvage) / v.life; return [['Annual depreciation', fmoney(d)], ['Monthly', fmoney(d / 12)]]; } });
  T('hourly-to-salary', 'Hourly to Salary Calculator', 'Business', 'hourly to salary calculator', 'Convert an hourly wage into weekly, monthly and annual pay.', { inputs: [{ k: 'rate', label: 'Hourly rate', v: 500, step: 'any' }, { k: 'hrs', label: 'Hours / week', v: 40, step: 'any' }], calc: function (v) { var wk = v.rate * v.hrs; return [['Weekly', fmoney(wk)], ['Monthly', fmoney(wk * 52 / 12)], ['Annual', fmoney(wk * 52)]]; } });
  T('salary-to-hourly', 'Salary to Hourly Calculator', 'Business', 'salary to hourly calculator', 'Convert an annual salary into an hourly rate.', { inputs: [{ k: 'sal', label: 'Annual salary', v: 1200000, step: 'any' }, { k: 'hrs', label: 'Hours / week', v: 40, step: 'any' }], calc: function (v) { return [['Hourly rate', fmoney(v.sal / (v.hrs * 52))], ['Monthly', fmoney(v.sal / 12)]]; } });
  T('overtime-pay', 'Overtime Pay Calculator', 'Business', 'overtime pay calculator', 'Calculate total pay including overtime hours.', { inputs: [{ k: 'rate', label: 'Hourly rate', v: 400, step: 'any' }, { k: 'reg', label: 'Regular hours', v: 40, step: 'any' }, { k: 'ot', label: 'Overtime hours', v: 8, step: 'any' }, { k: 'mult', label: 'OT multiplier', v: 1.5, step: 'any' }], calc: function (v) { var pay = v.rate * v.reg + v.rate * v.mult * v.ot; return [['Total pay', fmoney(pay)], ['Overtime pay', fmoney(v.rate * v.mult * v.ot)]]; } });
  T('commission', 'Commission Calculator', 'Business', 'commission calculator, sales', 'Calculate sales commission earnings.', { inputs: [{ k: 'sales', label: 'Sales amount', v: 500000, step: 'any' }, { k: 'rate', label: 'Commission (%)', v: 5, step: 'any' }], calc: function (v) { return [['Commission', fmoney(v.sales * v.rate / 100)]]; } });
  T('invoice', 'Invoice Total Calculator', 'Business', 'invoice calculator, total with tax', 'Calculate invoice total with tax and discount.', { inputs: [{ k: 'sub', label: 'Subtotal', v: 100000, step: 'any' }, { k: 'disc', label: 'Discount (%)', v: 10, step: 'any' }, { k: 'tax', label: 'Tax (%)', v: 18, step: 'any' }], calc: function (v) { var afterDisc = v.sub * (1 - v.disc / 100); var tax = afterDisc * v.tax / 100; return [['Total', fmoney(afterDisc + tax)], ['Tax', fmoney(tax)], ['Discount', fmoney(v.sub * v.disc / 100)]]; } });
  T('vat', 'VAT Calculator', 'Business', 'vat calculator, value added tax', 'Add or remove VAT from an amount.', { inputs: [{ k: 'amt', label: 'Amount', v: 1000, step: 'any' }, { k: 'rate', label: 'VAT rate (%)', v: 20, step: 'any' }, { k: 'dir', label: 'Direction', t: 'sel', v: 'add', opts: [opt('add', 'Add VAT'), opt('remove', 'Remove VAT')] }], calc: function (v) { if (v.dir === 'add') { var t = v.amt * v.rate / 100; return [['Total', fmoney(v.amt + t)], ['VAT', fmoney(t)]]; } var net = v.amt / (1 + v.rate / 100); return [['Net', fmoney(net)], ['VAT', fmoney(v.amt - net)]]; } });
  T('tip-split', 'Tip & Bill Split Calculator', 'Everyday', 'tip split calculator, bill split', 'Split a bill and tip between people.', { inputs: [{ k: 'bill', label: 'Bill amount', v: 2000, step: 'any' }, { k: 'tip', label: 'Tip (%)', v: 10, step: 'any' }, { k: 'people', label: 'People', v: 4, step: '1' }], calc: function (v) { var tip = v.bill * v.tip / 100, total = v.bill + tip; return [['Total', fmoney(total)], ['Per person', fmoney(total / v.people)], ['Tip', fmoney(tip)]]; } });
  T('gratuity', 'Gratuity Calculator', 'Financial', 'gratuity calculator india', 'Estimate gratuity payout based on salary and years of service.', { inputs: [{ k: 'salary', label: 'Last drawn monthly salary', v: 60000, step: 'any' }, { k: 'years', label: 'Years of service', v: 10, step: 'any' }], calc: function (v) { return [['Gratuity', fmoney(v.salary * 15 / 26 * v.years)]]; } });
  T('hra-exemption', 'HRA Exemption Calculator', 'Financial', 'hra exemption calculator', 'Estimate exempt house rent allowance (HRA).', { inputs: [{ k: 'basic', label: 'Basic salary (annual)', v: 600000, step: 'any' }, { k: 'hra', label: 'HRA received (annual)', v: 240000, step: 'any' }, { k: 'rent', label: 'Rent paid (annual)', v: 180000, step: 'any' }, { k: 'metro', label: 'Metro city?', t: 'sel', v: 'yes', opts: [opt('yes', 'Yes'), opt('no', 'No')] }], calc: function (v) { var a = v.hra, b = v.basic * (v.metro === 'yes' ? 0.5 : 0.4), c = Math.max(0, v.rent - 0.1 * v.basic); var ex = Math.min(a, b, c); return [['Exempt HRA', fmoney(ex)], ['Taxable HRA', fmoney(v.hra - ex)]]; } });
  T('ppf-maturity', 'PPF Maturity Calculator', 'Financial', 'ppf calculator, public provident fund', 'Project PPF maturity for yearly contributions.', { inputs: [{ k: 'amt', label: 'Yearly deposit', v: 150000, step: 'any' }, { k: 'r', label: 'Rate (% p.a.)', v: 7.1, step: 'any' }, { k: 't', label: 'Years', v: 15, step: 'any' }], calc: function (v) { var b = 0; for (var i = 0; i < v.t; i++) { b += v.amt; b += b * v.r / 100; } return [['Maturity', fmoney(b)], ['Invested', fmoney(v.amt * v.t)], ['Interest', fmoney(b - v.amt * v.t)]]; } });
  T('nps', 'NPS Calculator', 'Financial', 'nps calculator, national pension scheme', 'Project NPS corpus and pension at retirement.', { inputs: [{ k: 'mon', label: 'Monthly contribution', v: 5000, step: 'any' }, { k: 'r', label: 'Return (% p.a.)', v: 10, step: 'any' }, { k: 't', label: 'Years to retirement', v: 30, step: 'any' }, { k: 'ann', label: 'Annuity portion (%)', v: 40, step: 'any' }], calc: function (v) { var m = v.r / 1200, n = v.t * 12; var fv = m ? v.mon * (Math.pow(1 + m, n) - 1) / m : v.mon * n; var annuity = fv * v.ann / 100; return [['Corpus', fmoney(fv)], ['Lump sum', fmoney(fv - annuity)], ['Annuity (pension fund)', fmoney(annuity)]]; } });

  /* ===================== HEALTH (32) ===================== */
  T('bmi-metric', 'BMI Calculator (Metric)', 'Health', 'bmi calculator metric, body mass index', 'Calculate body mass index using height and weight.', { inputs: [{ k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }], calc: function (v) { var b = v.w / Math.pow(v.h / 100, 2); var cat = b < 18.5 ? 'Underweight' : b < 25 ? 'Normal' : b < 30 ? 'Overweight' : 'Obese'; return [['BMI', fnum(b, 1)], ['Category', cat]]; } });
  T('bmi-imperial', 'BMI Calculator (Imperial)', 'Health', 'bmi calculator imperial, pounds inches', 'Calculate BMI from pounds and inches.', { inputs: [{ k: 'w', label: 'Weight (lb)', v: 154, step: 'any' }, { k: 'h', label: 'Height (in)', v: 69, step: 'any' }], calc: function (v) { var b = 703 * v.w / (v.h * v.h); var cat = b < 18.5 ? 'Underweight' : b < 25 ? 'Normal' : b < 30 ? 'Overweight' : 'Obese'; return [['BMI', fnum(b, 1)], ['Category', cat]]; } });
  T('bmr-calc', 'BMR Calculator', 'Health', 'bmr calculator, basal metabolic rate', 'Estimate basal metabolic rate (Mifflin-St Jeor).', { inputs: [{ k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }, { k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }, { k: 'a', label: 'Age', v: 30, step: 'any' }], calc: function (v) { var b = 10 * v.w + 6.25 * v.h - 5 * v.a + (v.s === 'male' ? 5 : -161); return [['BMR', fnum(b, 0) + ' kcal/day']]; } });
  T('tdee', 'TDEE Calculator', 'Health', 'tdee calculator, daily energy expenditure', 'Estimate total daily energy expenditure.', { inputs: [{ k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }, { k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }, { k: 'a', label: 'Age', v: 30, step: 'any' }, { k: 'act', label: 'Activity', t: 'sel', v: '1.55', opts: [opt('1.2', 'Sedentary'), opt('1.375', 'Light'), opt('1.55', 'Moderate'), opt('1.725', 'Active'), opt('1.9', 'Very active')] }], calc: function (v) { var b = 10 * v.w + 6.25 * v.h - 5 * v.a + (v.s === 'male' ? 5 : -161); return [['TDEE', fnum(b * parseFloat(v.act), 0) + ' kcal/day']]; } });
  T('body-fat-navy', 'Body Fat Calculator (Navy)', 'Health', 'body fat calculator navy method', 'Estimate body fat percentage using the US Navy method.', { inputs: [{ k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }, { k: 'neck', label: 'Neck (cm)', v: 38, step: 'any' }, { k: 'waist', label: 'Waist (cm)', v: 85, step: 'any' }, { k: 'hip', label: 'Hip (cm, female)', v: 95, step: 'any' }], calc: function (v) { var bf; if (v.s === 'male') bf = 495 / (1.0324 - 0.19077 * Math.log10(v.waist - v.neck) + 0.15456 * Math.log10(v.h)) - 450; else bf = 495 / (1.29579 - 0.35004 * Math.log10(v.waist + v.hip - v.neck) + 0.221 * Math.log10(v.h)) - 450; return [['Body fat', fnum(bf, 1) + ' %']]; } });
  T('lean-body-mass', 'Lean Body Mass Calculator', 'Health', 'lean body mass calculator', 'Estimate lean body mass.', { inputs: [{ k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }, { k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }], calc: function (v) { var lbm = v.s === 'male' ? 0.407 * v.w + 0.267 * v.h - 19.2 : 0.252 * v.w + 0.473 * v.h - 48.3; return [['Lean body mass', fnum(lbm, 1) + ' kg'], ['Body fat mass', fnum(v.w - lbm, 1) + ' kg']]; } });
  T('ideal-body-weight', 'Ideal Body Weight Calculator', 'Health', 'ideal body weight calculator', 'Estimate ideal body weight (Devine formula).', { inputs: [{ k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }], calc: function (v) { var inchesOver5ft = Math.max(0, v.h / 2.54 - 60); var w = (v.s === 'male' ? 50 : 45.5) + 2.3 * inchesOver5ft; return [['Ideal weight', fnum(w, 1) + ' kg']]; } });
  T('calories-burned', 'Calories Burned Calculator', 'Health', 'calories burned calculator, exercise', 'Estimate calories burned during exercise from MET value.', { inputs: [{ k: 'met', label: 'MET value', v: 8, step: 'any' }, { k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'min', label: 'Minutes', v: 30, step: 'any' }], calc: function (v) { return [['Calories burned', fnum(v.met * 3.5 * v.w / 200 * v.min, 0) + ' kcal']]; } });
  T('macro', 'Macronutrient Calculator', 'Health', 'macro calculator, protein carbs fat', 'Split daily calories into protein, carbs and fat.', { inputs: [{ k: 'cal', label: 'Daily calories', v: 2000, step: 'any' }, { k: 'p', label: 'Protein (%)', v: 30, step: 'any' }, { k: 'c', label: 'Carbs (%)', v: 40, step: 'any' }, { k: 'f', label: 'Fat (%)', v: 30, step: 'any' }], calc: function (v) { return [['Protein', fnum(v.cal * v.p / 100 / 4, 0) + ' g'], ['Carbs', fnum(v.cal * v.c / 100 / 4, 0) + ' g'], ['Fat', fnum(v.cal * v.f / 100 / 9, 0) + ' g']]; } });
  T('water-intake-calc', 'Water Intake Calculator', 'Health', 'water intake calculator, daily water', 'Estimate recommended daily water intake.', { inputs: [{ k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'act', label: 'Exercise (minutes)', v: 30, step: 'any' }], calc: function (v) { var ml = v.w * 35 + v.act / 30 * 350; return [['Daily water', fnum(ml / 1000, 2) + ' L'], ['Glasses (250ml)', fnum(ml / 250, 0)]]; } });
  T('calorie-deficit', 'Calorie Deficit Calculator', 'Health', 'calorie deficit calculator, weight loss', 'Find the daily deficit to reach a weight-loss goal.', { inputs: [{ k: 'loss', label: 'Target loss (kg)', v: 5, step: 'any' }, { k: 'weeks', label: 'In weeks', v: 10, step: 'any' }], calc: function (v) { var deficit = v.loss * 7700 / (v.weeks * 7); return [['Daily deficit', fnum(deficit, 0) + ' kcal'], ['Weekly loss', fnum(v.loss / v.weeks, 2) + ' kg']]; } });
  T('protein-need', 'Daily Protein Calculator', 'Health', 'protein calculator, daily protein need', 'Estimate daily protein requirement.', { inputs: [{ k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'g', label: 'Goal', t: 'sel', v: '1.6', opts: [opt('0.8', 'Sedentary'), opt('1.2', 'Active'), opt('1.6', 'Build muscle'), opt('2', 'Athlete')] }], calc: function (v) { return [['Daily protein', fnum(v.w * parseFloat(v.g), 0) + ' g']]; } });
  T('waist-hip-ratio', 'Waist-to-Hip Ratio Calculator', 'Health', 'waist hip ratio calculator', 'Calculate waist-to-hip ratio and risk level.', { inputs: [{ k: 'waist', label: 'Waist (cm)', v: 85, step: 'any' }, { k: 'hip', label: 'Hip (cm)', v: 100, step: 'any' }, { k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }], calc: function (v) { var r = v.waist / v.hip; var risk = v.s === 'male' ? (r > 0.9 ? 'High' : 'Low') : (r > 0.85 ? 'High' : 'Low'); return [['Ratio', fnum(r, 2)], ['Risk', risk]]; } });
  T('waist-height-ratio', 'Waist-to-Height Ratio Calculator', 'Health', 'waist to height ratio calculator', 'Calculate waist-to-height ratio.', { inputs: [{ k: 'waist', label: 'Waist (cm)', v: 85, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }], calc: function (v) { var r = v.waist / v.h; return [['Ratio', fnum(r, 2)], ['Status', r < 0.5 ? 'Healthy' : 'Elevated']]; } });
  T('target-heart-rate', 'Target Heart Rate Calculator', 'Health', 'target heart rate calculator', 'Find your target heart-rate training zones.', { inputs: [{ k: 'age', label: 'Age', v: 30, step: 'any' }, { k: 'rest', label: 'Resting HR', v: 70, step: 'any' }], calc: function (v) { var max = 220 - v.age; return [['Max HR', fnum(max, 0) + ' bpm'], ['Fat burn (60%)', fnum((max - v.rest) * 0.6 + v.rest, 0) + ' bpm'], ['Cardio (80%)', fnum((max - v.rest) * 0.8 + v.rest, 0) + ' bpm']]; } });
  T('max-heart-rate', 'Maximum Heart Rate Calculator', 'Health', 'max heart rate calculator', 'Estimate maximum heart rate by age.', { inputs: [{ k: 'age', label: 'Age', v: 30, step: 'any' }], calc: function (v) { return [['Max HR (220-age)', fnum(220 - v.age, 0) + ' bpm'], ['Tanaka', fnum(208 - 0.7 * v.age, 0) + ' bpm']]; } });
  T('pregnancy-due-date', 'Pregnancy Due Date Calculator', 'Health', 'pregnancy due date calculator', 'Estimate a due date from the last menstrual period.', { inputs: [{ k: 'lmp', label: 'Last period date', t: 'date', v: '' }], calc: function (v) { if (!v.lmp) return [['Result', 'Pick a date']]; var d = new Date(v.lmp); d.setDate(d.getDate() + 280); return [['Estimated due date', d.toDateString()]]; } });
  T('ovulation', 'Ovulation Calculator', 'Health', 'ovulation calculator, fertile window', 'Estimate ovulation and fertile window.', { inputs: [{ k: 'lmp', label: 'Last period date', t: 'date', v: '' }, { k: 'len', label: 'Cycle length (days)', v: 28, step: '1' }], calc: function (v) { if (!v.lmp) return [['Result', 'Pick a date']]; var d = new Date(v.lmp); d.setDate(d.getDate() + v.len - 14); var s = new Date(d); s.setDate(s.getDate() - 4); return [['Ovulation day', d.toDateString()], ['Fertile window starts', s.toDateString()]]; } });
  T('child-height', 'Child Height Predictor', 'Health', 'child height predictor calculator', 'Predict a child\u2019s adult height from parents\u2019 heights.', { inputs: [{ k: 'mom', label: 'Mother height (cm)', v: 162, step: 'any' }, { k: 'dad', label: 'Father height (cm)', v: 178, step: 'any' }, { k: 's', label: 'Child sex', t: 'sel', v: 'boy', opts: [opt('boy', 'Boy'), opt('girl', 'Girl')] }], calc: function (v) { var h = v.s === 'boy' ? (v.mom + v.dad + 13) / 2 : (v.mom + v.dad - 13) / 2; return [['Predicted height', fnum(h, 1) + ' cm'], ['Range', fnum(h - 8, 0) + '\u2013' + fnum(h + 8, 0) + ' cm']]; } });
  T('bsa', 'Body Surface Area Calculator', 'Health', 'body surface area calculator, bsa', 'Estimate body surface area (Mosteller).', { inputs: [{ k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }], calc: function (v) { return [['BSA', fnum(Math.sqrt(v.h * v.w / 3600), 3) + ' m\u00B2']]; } });
  T('calorie-goal', 'Weight Goal Calorie Calculator', 'Health', 'calorie goal calculator', 'Find daily calories for losing, maintaining or gaining weight.', { inputs: [{ k: 'tdee', label: 'Maintenance calories', v: 2200, step: 'any' }, { k: 'goal', label: 'Goal', t: 'sel', v: 'lose', opts: [opt('lose', 'Lose weight'), opt('maintain', 'Maintain'), opt('gain', 'Gain weight')] }], calc: function (v) { var cal = v.goal === 'lose' ? v.tdee - 500 : v.goal === 'gain' ? v.tdee + 500 : v.tdee; return [['Daily calories', fnum(cal, 0) + ' kcal']]; } });
  T('alcohol-units', 'Alcohol Units Calculator', 'Health', 'alcohol units calculator', 'Calculate units of alcohol in a drink.', { inputs: [{ k: 'ml', label: 'Volume (ml)', v: 330, step: 'any' }, { k: 'abv', label: 'ABV (%)', v: 5, step: 'any' }], calc: function (v) { return [['Units', fnum(v.ml * v.abv / 1000, 2)]]; } });
  T('smoking-cost', 'Smoking Cost Calculator', 'Health', 'smoking cost calculator, quit smoking savings', 'See how much smoking costs you over time.', { inputs: [{ k: 'cigs', label: 'Cigarettes / day', v: 10, step: 'any' }, { k: 'pack', label: 'Cigarettes / pack', v: 20, step: 'any' }, { k: 'price', label: 'Price / pack', v: 300, step: 'any' }], calc: function (v) { var day = v.cigs / v.pack * v.price; return [['Daily', fmoney(day)], ['Monthly', fmoney(day * 30)], ['Yearly', fmoney(day * 365)]]; } });
  T('sleep-cycle', 'Sleep Cycle Calculator', 'Health', 'sleep cycle calculator, bedtime', 'Find ideal bedtimes based on 90-minute sleep cycles.', { inputs: [{ k: 'wake', label: 'Wake-up time', t: 'time', v: '06:30' }], calc: function (v) { if (!v.wake) return [['Result', 'Pick a time']]; var p = v.wake.split(':'), d = new Date(); d.setHours(+p[0], +p[1], 0, 0); var out = []; [6, 5, 4].forEach(function (c) { var b = new Date(d.getTime() - c * 90 * 60000); out.push([c + ' cycles', pad2(b.getHours()) + ':' + pad2(b.getMinutes())]); }); return out; } });
  T('water-percent', 'Body Water Percentage Calculator', 'Health', 'body water percentage calculator', 'Estimate total body water percentage.', { inputs: [{ k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }, { k: 'age', label: 'Age', v: 30, step: 'any' }], calc: function (v) { var p = v.s === 'male' ? (v.age < 51 ? 60 : 55) : (v.age < 51 ? 50 : 47); return [['Body water', fnum(p, 0) + ' %']]; } });
  T('ponderal-index', 'Ponderal Index Calculator', 'Health', 'ponderal index calculator', 'Calculate the ponderal (corpulence) index.', { inputs: [{ k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }], calc: function (v) { return [['Ponderal index', fnum(v.w / Math.pow(v.h / 100, 3), 2)]]; } });
  T('blood-volume', 'Blood Volume Calculator', 'Health', 'blood volume calculator', 'Estimate total blood volume (Nadler).', { inputs: [{ k: 's', label: 'Sex', t: 'sel', v: 'male', opts: [opt('male', 'Male'), opt('female', 'Female')] }, { k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }, { k: 'h', label: 'Height (cm)', v: 175, step: 'any' }], calc: function (v) { var m = v.h / 100; var bv = v.s === 'male' ? 0.3669 * Math.pow(m, 3) + 0.03219 * v.w + 0.6041 : 0.3561 * Math.pow(m, 3) + 0.03308 * v.w + 0.1833; return [['Blood volume', fnum(bv, 2) + ' L']]; } });
  T('vo2max', 'VO2 Max Calculator', 'Health', 'vo2 max calculator, fitness', 'Estimate VO2 max from a 1.5-mile run time.', { inputs: [{ k: 'min', label: 'Run time (minutes)', v: 12, step: 'any' }], calc: function (v) { return [['VO2 max', fnum(483 / v.min + 3.5, 1) + ' ml/kg/min']]; } });
  T('steps-to-calories', 'Steps to Calories Calculator', 'Health', 'steps to calories calculator', 'Convert your step count into calories burned.', { inputs: [{ k: 'steps', label: 'Steps', v: 10000, step: 'any' }, { k: 'w', label: 'Weight (kg)', v: 70, step: 'any' }], calc: function (v) { return [['Calories', fnum(v.steps * 0.0005 * v.w, 0) + ' kcal'], ['Distance', fnum(v.steps * 0.762 / 1000, 2) + ' km']]; } });
  T('cigarettes-life', 'Smoking Life Impact Calculator', 'Health', 'smoking life expectancy calculator', 'Estimate time lost from smoking (11 min per cigarette).', { inputs: [{ k: 'cigs', label: 'Cigarettes / day', v: 10, step: 'any' }, { k: 'years', label: 'Years smoking', v: 10, step: 'any' }], calc: function (v) { var mins = v.cigs * v.years * 365 * 11; return [['Days lost (est.)', fnum(mins / 60 / 24, 0)], ['Cigarettes smoked', fnum(v.cigs * v.years * 365, 0)]]; } });
  T('daily-calorie-burn', 'Resting Calorie Burn Calculator', 'Health', 'resting calorie burn calculator', 'Estimate calories burned at rest per day.', { inputs: [{ k: 'bmr', label: 'BMR (kcal)', v: 1600, step: 'any' }, { k: 'hours', label: 'Resting hours', v: 24, step: 'any' }], calc: function (v) { return [['Calories at rest', fnum(v.bmr / 24 * v.hours, 0) + ' kcal']]; } });
