  T('date-difference', 'Date Difference Calculator', 'Date & Time', 'date difference calculator, days between dates', 'Find the number of days, weeks and months between two dates.', { inputs: [{ k: 'a', label: 'Start date', t: 'date', v: '' }, { k: 'b', label: 'End date', t: 'date', v: '' }], calc: function (v) { if (!v.a || !v.b) return [['Result', 'Pick two dates']]; var d = Math.abs(new Date(v.b) - new Date(v.a)) / 86400000; return [['Days', fnum(d, 0)], ['Weeks', fnum(d / 7, 1)], ['Months', fnum(d / 30.44, 1)]]; } });
  T('age-detailed', 'Age Calculator', 'Date & Time', 'age calculator, exact age', 'Calculate exact age in years, months and days.', { inputs: [{ k: 'dob', label: 'Date of birth', t: 'date', v: '' }], calc: function (v) { if (!v.dob) return [['Result', 'Pick a date']]; var b = new Date(v.dob), n = new Date(); var y = n.getFullYear() - b.getFullYear(), m = n.getMonth() - b.getMonth(), d = n.getDate() - b.getDate(); if (d < 0) { m--; d += 30; } if (m < 0) { y--; m += 12; } return [['Age', y + ' yr ' + m + ' mo ' + d + ' d'], ['Total days', fnum((n - b) / 86400000, 0)]]; } });
  T('add-days', 'Add or Subtract Days Calculator', 'Date & Time', 'add days to date calculator', 'Add or subtract days from a date.', { inputs: [{ k: 'd', label: 'Date', t: 'date', v: '' }, { k: 'n', label: 'Days (+/-)', v: 30, step: '1' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var x = new Date(v.d); x.setDate(x.getDate() + v.n); return [['Result date', x.toDateString()]]; } });
  T('add-weeks', 'Add Weeks Calculator', 'Date & Time', 'add weeks to date calculator', 'Add or subtract weeks from a date.', { inputs: [{ k: 'd', label: 'Date', t: 'date', v: '' }, { k: 'n', label: 'Weeks (+/-)', v: 4, step: '1' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var x = new Date(v.d); x.setDate(x.getDate() + v.n * 7); return [['Result date', x.toDateString()]]; } });
  T('add-months', 'Add Months Calculator', 'Date & Time', 'add months to date calculator', 'Add or subtract months from a date.', { inputs: [{ k: 'd', label: 'Date', t: 'date', v: '' }, { k: 'n', label: 'Months (+/-)', v: 6, step: '1' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var x = new Date(v.d); x.setMonth(x.getMonth() + v.n); return [['Result date', x.toDateString()]]; } });
  T('business-days', 'Business Days Calculator', 'Date & Time', 'business days calculator, working days', 'Count working days between two dates.', { inputs: [{ k: 'a', label: 'Start date', t: 'date', v: '' }, { k: 'b', label: 'End date', t: 'date', v: '' }], calc: function (v) { if (!v.a || !v.b) return [['Result', 'Pick two dates']]; var s = new Date(v.a), e = new Date(v.b), c = 0; while (s <= e) { var d = s.getDay(); if (d !== 0 && d !== 6) c++; s.setDate(s.getDate() + 1); } return [['Working days', c]]; } });
  T('week-number', 'Week Number Calculator', 'Date & Time', 'week number calculator', 'Find the ISO week number for any date.', { inputs: [{ k: 'd', label: 'Date', t: 'date', v: '' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var dt = new Date(v.d); var on = new Date(Date.UTC(dt.getFullYear(), dt.getMonth(), dt.getDate())); var day = on.getUTCDay() || 7; on.setUTCDate(on.getUTCDate() + 4 - day); var ys = new Date(Date.UTC(on.getUTCFullYear(), 0, 1)); var wk = Math.ceil(((on - ys) / 86400000 + 1) / 7); return [['Week number', wk], ['Year', on.getUTCFullYear()]]; } });
  T('days-until', 'Days Until Date Calculator', 'Date & Time', 'days until date calculator, countdown', 'Count down the days until a future date.', { inputs: [{ k: 'd', label: 'Target date', t: 'date', v: '' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var diff = Math.ceil((new Date(v.d) - new Date()) / 86400000); return [['Days remaining', diff], ['Weeks', fnum(diff / 7, 1)]]; } });
  T('time-duration', 'Time Duration Calculator', 'Date & Time', 'time duration calculator, hours between times', 'Find the duration between two times.', { inputs: [{ k: 'a', label: 'Start time', t: 'time', v: '09:00' }, { k: 'b', label: 'End time', t: 'time', v: '17:30' }], calc: function (v) { if (!v.a || !v.b) return [['Result', 'Pick times']]; var pa = v.a.split(':'), pb = v.b.split(':'); var mins = (+pb[0] * 60 + +pb[1]) - (+pa[0] * 60 + +pa[1]); if (mins < 0) mins += 1440; return [['Duration', Math.floor(mins / 60) + ' h ' + (mins % 60) + ' m'], ['Total minutes', mins]]; } });
  T('add-time', 'Add Time Calculator', 'Date & Time', 'add time calculator, add hours minutes', 'Add hours and minutes to a time.', { inputs: [{ k: 't', label: 'Start time', t: 'time', v: '10:00' }, { k: 'h', label: 'Add hours', v: 2, step: '1' }, { k: 'm', label: 'Add minutes', v: 30, step: '1' }], calc: function (v) { if (!v.t) return [['Result', 'Pick a time']]; var p = v.t.split(':'); var total = (+p[0] * 60 + +p[1] + v.h * 60 + v.m) % 1440; if (total < 0) total += 1440; return [['Result time', pad2(Math.floor(total / 60)) + ':' + pad2(total % 60)]]; } });
  T('hours-calculator', 'Hours Calculator', 'Date & Time', 'hours calculator, work hours', 'Add up multiple time spans into total hours.', { inputs: [{ k: 'h', label: 'Hours', v: 8, step: 'any' }, { k: 'm', label: 'Minutes', v: 45, step: 'any' }, { k: 'days', label: 'Number of days', v: 5, step: 'any' }], calc: function (v) { var perDay = v.h + v.m / 60; return [['Per day', fnum(perDay, 2) + ' h'], ['Total', fnum(perDay * v.days, 2) + ' h']]; } });
  T('countdown-timer', 'Countdown Calculator', 'Date & Time', 'countdown calculator, time until event', 'Count down to a date and time.', { inputs: [{ k: 'd', label: 'Event date', t: 'date', v: '' }, { k: 't', label: 'Event time', t: 'time', v: '00:00' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var target = new Date(v.d + 'T' + (v.t || '00:00')); var ms = target - new Date(); if (ms < 0) return [['Status', 'Event passed']]; var s = ms / 1000; return [['Days', Math.floor(s / 86400)], ['Hours', Math.floor(s / 3600) % 24], ['Minutes', Math.floor(s / 60) % 60]]; } });
  T('day-of-week', 'Day of the Week Calculator', 'Date & Time', 'day of week calculator', 'Find which day of the week a date falls on.', { inputs: [{ k: 'd', label: 'Date', t: 'date', v: '' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; return [['Day', new Date(v.d).toLocaleDateString('en-US', { weekday: 'long' })]]; } });
  T('leap-year-check', 'Leap Year Calculator', 'Date & Time', 'leap year calculator', 'Check whether a year is a leap year.', { inputs: [{ k: 'y', label: 'Year', v: 2024, step: '1' }], calc: function (v) { var y = Math.round(v.y); var leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0; return [[y + ' is', leap ? 'Leap year (366 days)' : 'Not a leap year (365 days)']]; } });
  T('zodiac', 'Zodiac Sign Calculator', 'Date & Time', 'zodiac sign calculator, star sign', 'Find your astrological zodiac sign from your birthday.', { inputs: [{ k: 'd', label: 'Date of birth', t: 'date', v: '' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var dt = new Date(v.d), m = dt.getMonth() + 1, day = dt.getDate(); var z = [[1, 20, 'Aquarius'], [2, 19, 'Pisces'], [3, 21, 'Aries'], [4, 20, 'Taurus'], [5, 21, 'Gemini'], [6, 21, 'Cancer'], [7, 23, 'Leo'], [8, 23, 'Virgo'], [9, 23, 'Libra'], [10, 23, 'Scorpio'], [11, 22, 'Sagittarius'], [12, 22, 'Capricorn']]; var sign = (day < z[m - 1][1]) ? z[(m + 10) % 12][2] : z[m - 1][2]; return [['Zodiac sign', sign]]; } });
  T('chinese-zodiac', 'Chinese Zodiac Calculator', 'Date & Time', 'chinese zodiac calculator', 'Find your Chinese zodiac animal by birth year.', { inputs: [{ k: 'y', label: 'Birth year', v: 1995, step: '1' }], calc: function (v) { var a = ['Monkey', 'Rooster', 'Dog', 'Pig', 'Rat', 'Ox', 'Tiger', 'Rabbit', 'Dragon', 'Snake', 'Horse', 'Goat']; return [['Animal', a[Math.round(v.y) % 12]]]; } });
  T('age-on-planet', 'Age on Other Planets', 'Date & Time', 'age on other planets calculator', 'See your age on other planets.', { inputs: [{ k: 'dob', label: 'Date of birth', t: 'date', v: '' }], calc: function (v) { if (!v.dob) return [['Result', 'Pick a date']]; var days = (new Date() - new Date(v.dob)) / 86400000; return [['Mars', fnum(days / 687, 1) + ' yr'], ['Venus', fnum(days / 225, 1) + ' yr'], ['Jupiter', fnum(days / 4333, 1) + ' yr']]; } });
  T('working-hours-pay', 'Working Hours to Pay Calculator', 'Date & Time', 'working hours pay calculator', 'Convert worked hours into pay at an hourly rate.', { inputs: [{ k: 'h', label: 'Hours worked', v: 160, step: 'any' }, { k: 'rate', label: 'Hourly rate', v: 350, step: 'any' }], calc: function (v) { return [['Total pay', fmoney(v.h * v.rate)]]; } });
  T('time-card', 'Time Card Calculator', 'Date & Time', 'time card calculator, clock in out', 'Calculate hours worked from clock-in and clock-out, minus a break.', { inputs: [{ k: 'in', label: 'Clock in', t: 'time', v: '09:00' }, { k: 'out', label: 'Clock out', t: 'time', v: '18:00' }, { k: 'brk', label: 'Break (minutes)', v: 60, step: 'any' }], calc: function (v) { if (!v.in || !v.out) return [['Result', 'Pick times']]; var pi = v.in.split(':'), po = v.out.split(':'); var mins = (+po[0] * 60 + +po[1]) - (+pi[0] * 60 + +pi[1]) - v.brk; if (mins < 0) mins += 1440; return [['Hours worked', fnum(mins / 60, 2)], ['Minutes', mins]]; } });
  T('millennium', 'Days Alive Calculator', 'Date & Time', 'days alive calculator, how long have i lived', 'Find out how many days, hours and minutes you have been alive.', { inputs: [{ k: 'dob', label: 'Date of birth', t: 'date', v: '' }], calc: function (v) { if (!v.dob) return [['Result', 'Pick a date']]; var ms = new Date() - new Date(v.dob); return [['Days', fnum(ms / 86400000, 0)], ['Hours', fnum(ms / 3600000, 0)], ['Minutes', fnum(ms / 60000, 0)]]; } });
  T('retirement-date', 'Retirement Date Calculator', 'Date & Time', 'retirement date calculator', 'Find your retirement date and time remaining.', { inputs: [{ k: 'dob', label: 'Date of birth', t: 'date', v: '' }, { k: 'age', label: 'Retirement age', v: 60, step: '1' }], calc: function (v) { if (!v.dob) return [['Result', 'Pick a date']]; var d = new Date(v.dob); d.setFullYear(d.getFullYear() + v.age); var yrs = (d - new Date()) / 31557600000; return [['Retirement date', d.toDateString()], ['Years left', fnum(yrs, 1)]]; } });
  T('anniversary', 'Anniversary Calculator', 'Date & Time', 'anniversary calculator, years together', 'Find how long since a special date and the next anniversary.', { inputs: [{ k: 'd', label: 'Special date', t: 'date', v: '' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var start = new Date(v.d), now = new Date(); var yrs = (now - start) / 31557600000; var next = new Date(start); next.setFullYear(now.getFullYear() + (next < now ? 1 : 0)); return [['Time elapsed', fnum(yrs, 2) + ' years'], ['Next anniversary', next.toDateString()]]; } });
  T('time-zone-offset', 'Time Zone Offset Calculator', 'Date & Time', 'time zone offset calculator', 'Convert a time across two UTC offsets.', { inputs: [{ k: 't', label: 'Time', t: 'time', v: '12:00' }, { k: 'from', label: 'From UTC offset', v: 5.5, step: 'any' }, { k: 'to', label: 'To UTC offset', v: -5, step: 'any' }], calc: function (v) { if (!v.t) return [['Result', 'Pick a time']]; var p = v.t.split(':'); var mins = (+p[0] * 60 + +p[1]) + (v.to - v.from) * 60; mins = ((mins % 1440) + 1440) % 1440; return [['Converted time', pad2(Math.floor(mins / 60)) + ':' + pad2(Math.round(mins % 60))]]; } });

