  T('paint', 'Paint Calculator', 'Construction', 'paint calculator, wall paint coverage', 'Estimate litres of paint needed for walls.', { inputs: [{ k: 'area', label: 'Wall area (m\u00B2)', v: 50, step: 'any' }, { k: 'coats', label: 'Coats', v: 2, step: '1' }, { k: 'cov', label: 'Coverage (m\u00B2 / L)', v: 10, step: 'any' }], calc: function (v) { var l = v.area * v.coats / v.cov; return [['Paint needed', fnum(l, 2) + ' L'], ['Approx cans (4L)', fnum(Math.ceil(l / 4), 0)]]; } });
  T('tile', 'Tile Calculator', 'Construction', 'tile calculator, floor tiles', 'Estimate number of tiles needed for a floor.', { inputs: [{ k: 'area', label: 'Floor area (m\u00B2)', v: 30, step: 'any' }, { k: 'tw', label: 'Tile width (cm)', v: 60, step: 'any' }, { k: 'th', label: 'Tile height (cm)', v: 60, step: 'any' }, { k: 'waste', label: 'Wastage (%)', v: 10, step: 'any' }], calc: function (v) { var tileArea = (v.tw / 100) * (v.th / 100); var n = v.area / tileArea * (1 + v.waste / 100); return [['Tiles needed', fnum(Math.ceil(n), 0)]]; } });
  T('flooring', 'Flooring Calculator', 'Construction', 'flooring calculator, laminate cost', 'Estimate flooring material and cost.', { inputs: [{ k: 'l', label: 'Room length (m)', v: 6, step: 'any' }, { k: 'w', label: 'Room width (m)', v: 5, step: 'any' }, { k: 'price', label: 'Price per m\u00B2', v: 800, step: 'any' }], calc: function (v) { var a = v.l * v.w; return [['Area', fnum(a, 2) + ' m\u00B2'], ['Total cost', fmoney(a * v.price)]]; } });
  T('concrete', 'Concrete Calculator', 'Construction', 'concrete calculator, cement volume', 'Estimate concrete volume for a slab.', { inputs: [{ k: 'l', label: 'Length (m)', v: 5, step: 'any' }, { k: 'w', label: 'Width (m)', v: 4, step: 'any' }, { k: 'd', label: 'Depth (m)', v: 0.15, step: 'any' }], calc: function (v) { var vol = v.l * v.w * v.d; return [['Volume', fnum(vol, 3) + ' m\u00B3'], ['Cement bags (~7/m\u00B3)', fnum(Math.ceil(vol * 7), 0)]]; } });
  T('brick', 'Brick Calculator', 'Construction', 'brick calculator, wall bricks', 'Estimate the number of bricks for a wall.', { inputs: [{ k: 'area', label: 'Wall area (m\u00B2)', v: 20, step: 'any' }, { k: 'per', label: 'Bricks per m\u00B2', v: 60, step: 'any' }], calc: function (v) { return [['Bricks needed', fnum(Math.ceil(v.area * v.per), 0)]]; } });
  T('plaster', 'Plaster Calculator', 'Construction', 'plaster calculator, cement sand', 'Estimate cement and sand for plastering.', { inputs: [{ k: 'area', label: 'Area (m\u00B2)', v: 30, step: 'any' }, { k: 'thick', label: 'Thickness (mm)', v: 12, step: 'any' }], calc: function (v) { var vol = v.area * v.thick / 1000 * 1.3; return [['Mortar volume', fnum(vol, 3) + ' m\u00B3'], ['Cement bags (1:4)', fnum(Math.ceil(vol / 5 * 6), 0)]]; } });
  T('roof-pitch', 'Roof Pitch Calculator', 'Construction', 'roof pitch calculator, slope angle', 'Convert roof rise and run into pitch angle.', { inputs: [{ k: 'rise', label: 'Rise', v: 4, step: 'any' }, { k: 'run', label: 'Run', v: 12, step: 'any' }], calc: function (v) { return [['Angle', fnum(Math.atan(v.rise / v.run) * 180 / Math.PI, 2) + '\u00B0'], ['Pitch', v.rise + ':' + v.run]]; } });
  T('stair', 'Stair Calculator', 'Construction', 'stair calculator, steps riser', 'Calculate the number of steps and riser height.', { inputs: [{ k: 'height', label: 'Total rise (cm)', v: 280, step: 'any' }, { k: 'riser', label: 'Target riser (cm)', v: 18, step: 'any' }], calc: function (v) { var steps = Math.round(v.height / v.riser); return [['Number of steps', steps], ['Actual riser', fnum(v.height / steps, 2) + ' cm']]; } });
  T('drywall', 'Drywall Calculator', 'Construction', 'drywall calculator, sheets', 'Estimate drywall sheets for a surface area.', { inputs: [{ k: 'area', label: 'Area (m\u00B2)', v: 60, step: 'any' }, { k: 'sheet', label: 'Sheet size (m\u00B2)', v: 2.88, step: 'any' }], calc: function (v) { return [['Sheets needed', fnum(Math.ceil(v.area / v.sheet * 1.1), 0)]]; } });
  T('wallpaper', 'Wallpaper Calculator', 'Construction', 'wallpaper calculator, rolls', 'Estimate wallpaper rolls for a room.', { inputs: [{ k: 'perimeter', label: 'Room perimeter (m)', v: 20, step: 'any' }, { k: 'height', label: 'Wall height (m)', v: 2.7, step: 'any' }, { k: 'roll', label: 'Roll covers (m\u00B2)', v: 5, step: 'any' }], calc: function (v) { return [['Rolls needed', fnum(Math.ceil(v.perimeter * v.height / v.roll * 1.1), 0)]]; } });
  T('gravel', 'Gravel Calculator', 'Construction', 'gravel calculator, aggregate weight', 'Estimate gravel volume and weight.', { inputs: [{ k: 'l', label: 'Length (m)', v: 5, step: 'any' }, { k: 'w', label: 'Width (m)', v: 3, step: 'any' }, { k: 'd', label: 'Depth (cm)', v: 10, step: 'any' }], calc: function (v) { var vol = v.l * v.w * v.d / 100; return [['Volume', fnum(vol, 3) + ' m\u00B3'], ['Weight (~1.6 t/m\u00B3)', fnum(vol * 1.6, 2) + ' t']]; } });
  T('mulch', 'Mulch Calculator', 'Construction', 'mulch calculator, garden', 'Estimate mulch needed for a garden bed.', { inputs: [{ k: 'area', label: 'Bed area (m\u00B2)', v: 20, step: 'any' }, { k: 'depth', label: 'Depth (cm)', v: 5, step: 'any' }], calc: function (v) { return [['Mulch volume', fnum(v.area * v.depth / 100, 3) + ' m\u00B3']]; } });
  T('fence', 'Fence Calculator', 'Construction', 'fence calculator, posts panels', 'Estimate fence posts and panels.', { inputs: [{ k: 'len', label: 'Fence length (m)', v: 30, step: 'any' }, { k: 'spacing', label: 'Post spacing (m)', v: 2.5, step: 'any' }], calc: function (v) { var posts = Math.ceil(v.len / v.spacing) + 1; return [['Posts', posts], ['Panels', posts - 1]]; } });
  T('rebar', 'Rebar Calculator', 'Construction', 'rebar calculator, reinforcement', 'Estimate rebar pieces for a grid.', { inputs: [{ k: 'l', label: 'Slab length (m)', v: 5, step: 'any' }, { k: 'w', label: 'Slab width (m)', v: 4, step: 'any' }, { k: 'spacing', label: 'Bar spacing (cm)', v: 20, step: 'any' }], calc: function (v) { var bx = Math.floor(v.w / (v.spacing / 100)) + 1; var by = Math.floor(v.l / (v.spacing / 100)) + 1; return [['Bars (length-wise)', bx], ['Bars (width-wise)', by], ['Total length', fnum(bx * v.l + by * v.w, 1) + ' m']]; } });
  T('insulation', 'Insulation Calculator', 'Construction', 'insulation calculator, r-value', 'Estimate insulation area and rolls.', { inputs: [{ k: 'area', label: 'Area (m\u00B2)', v: 80, step: 'any' }, { k: 'roll', label: 'Roll covers (m\u00B2)', v: 8, step: 'any' }], calc: function (v) { return [['Rolls needed', fnum(Math.ceil(v.area / v.roll), 0)]]; } });
  T('asphalt', 'Asphalt Calculator', 'Construction', 'asphalt calculator, driveway', 'Estimate asphalt tonnage for a driveway.', { inputs: [{ k: 'l', label: 'Length (m)', v: 10, step: 'any' }, { k: 'w', label: 'Width (m)', v: 3, step: 'any' }, { k: 'd', label: 'Depth (cm)', v: 5, step: 'any' }], calc: function (v) { var vol = v.l * v.w * v.d / 100; return [['Volume', fnum(vol, 3) + ' m\u00B3'], ['Weight (~2.4 t/m\u00B3)', fnum(vol * 2.4, 2) + ' t']]; } });
  T('board-feet', 'Board Feet Calculator', 'Construction', 'board feet calculator, lumber', 'Calculate board feet of lumber.', { inputs: [{ k: 'l', label: 'Length (in)', v: 96, step: 'any' }, { k: 'w', label: 'Width (in)', v: 6, step: 'any' }, { k: 't', label: 'Thickness (in)', v: 2, step: 'any' }, { k: 'qty', label: 'Pieces', v: 1, step: '1' }], calc: function (v) { return [['Board feet', fnum(v.l * v.w * v.t / 144 * v.qty, 2)]]; } });
  T('cubic-yards', 'Cubic Yards Calculator', 'Construction', 'cubic yards calculator', 'Convert dimensions into cubic yards.', { inputs: [{ k: 'l', label: 'Length (ft)', v: 10, step: 'any' }, { k: 'w', label: 'Width (ft)', v: 10, step: 'any' }, { k: 'd', label: 'Depth (ft)', v: 0.5, step: 'any' }], calc: function (v) { return [['Cubic yards', fnum(v.l * v.w * v.d / 27, 3)], ['Cubic feet', fnum(v.l * v.w * v.d, 2)]]; } });
  T('square-footage', 'Square Footage Calculator', 'Construction', 'square footage calculator, area', 'Calculate area in square feet and meters.', { inputs: [{ k: 'l', label: 'Length (ft)', v: 12, step: 'any' }, { k: 'w', label: 'Width (ft)', v: 10, step: 'any' }], calc: function (v) { var sf = v.l * v.w; return [['Square feet', fnum(sf, 2)], ['Square meters', fnum(sf * 0.092903, 2)]]; } });
  T('soil', 'Topsoil Calculator', 'Construction', 'topsoil calculator, garden soil', 'Estimate topsoil volume and weight for a bed.', { inputs: [{ k: 'l', label: 'Length (m)', v: 4, step: 'any' }, { k: 'w', label: 'Width (m)', v: 3, step: 'any' }, { k: 'd', label: 'Depth (cm)', v: 15, step: 'any' }], calc: function (v) { var vol = v.l * v.w * v.d / 100; return [['Volume', fnum(vol, 3) + ' m\u00B3'], ['Weight (~1.3 t/m\u00B3)', fnum(vol * 1.3, 2) + ' t']]; } });

  /* ===================== AUTOMOTIVE (12) ===================== */
  T('mileage', 'Mileage Calculator', 'Automotive', 'mileage calculator, fuel efficiency', 'Calculate fuel efficiency from distance and fuel used.', { inputs: [{ k: 'dist', label: 'Distance (km)', v: 450, step: 'any' }, { k: 'fuel', label: 'Fuel used (L)', v: 30, step: 'any' }], calc: function (v) { return [['Mileage', fnum(v.dist / v.fuel, 2) + ' km/L'], ['Consumption', fnum(v.fuel / v.dist * 100, 2) + ' L/100km']]; } });
  T('trip-fuel-cost', 'Trip Fuel Cost Calculator', 'Automotive', 'trip fuel cost calculator', 'Estimate the fuel cost of a road trip.', { inputs: [{ k: 'dist', label: 'Distance (km)', v: 500, step: 'any' }, { k: 'mileage', label: 'Mileage (km/L)', v: 15, step: 'any' }, { k: 'price', label: 'Fuel price / L', v: 105, step: 'any' }], calc: function (v) { var fuel = v.dist / v.mileage; return [['Fuel needed', fnum(fuel, 2) + ' L'], ['Total cost', fmoney(fuel * v.price)]]; } });
  T('fuel-savings', 'Fuel Savings Calculator', 'Automotive', 'fuel savings calculator, mpg comparison', 'Compare annual fuel cost of two vehicles.', { inputs: [{ k: 'km', label: 'Annual distance (km)', v: 15000, step: 'any' }, { k: 'm1', label: 'Old mileage (km/L)', v: 10, step: 'any' }, { k: 'm2', label: 'New mileage (km/L)', v: 18, step: 'any' }, { k: 'price', label: 'Fuel price / L', v: 105, step: 'any' }], calc: function (v) { var c1 = v.km / v.m1 * v.price, c2 = v.km / v.m2 * v.price; return [['Old cost', fmoney(c1)], ['New cost', fmoney(c2)], ['Annual saving', fmoney(c1 - c2)]]; } });
  T('ev-charging-cost', 'EV Charging Cost Calculator', 'Automotive', 'ev charging cost calculator', 'Estimate the cost to charge an electric vehicle.', { inputs: [{ k: 'kwh', label: 'Battery size (kWh)', v: 40, step: 'any' }, { k: 'rate', label: 'Electricity rate / kWh', v: 8, step: 'any' }, { k: 'pct', label: 'Charge amount (%)', v: 80, step: 'any' }], calc: function (v) { var used = v.kwh * v.pct / 100; return [['Energy', fnum(used, 2) + ' kWh'], ['Cost', fmoney(used * v.rate)]]; } });
  T('ev-vs-petrol', 'EV vs Petrol Cost Calculator', 'Automotive', 'ev vs petrol cost calculator', 'Compare running cost per km of an EV and a petrol car.', { inputs: [{ k: 'dist', label: 'Distance (km)', v: 100, step: 'any' }, { k: 'evk', label: 'EV km per kWh', v: 6, step: 'any' }, { k: 'erate', label: 'Electricity / kWh', v: 8, step: 'any' }, { k: 'kmpl', label: 'Petrol km/L', v: 15, step: 'any' }, { k: 'fuel', label: 'Fuel / L', v: 105, step: 'any' }], calc: function (v) { var ev = v.dist / v.evk * v.erate, pet = v.dist / v.kmpl * v.fuel; return [['EV cost', fmoney(ev)], ['Petrol cost', fmoney(pet)], ['You save', fmoney(pet - ev)]]; } });
  T('engine-displacement', 'Engine Displacement Calculator', 'Automotive', 'engine displacement calculator, cc', 'Calculate engine displacement from bore and stroke.', { inputs: [{ k: 'bore', label: 'Bore (mm)', v: 80, step: 'any' }, { k: 'stroke', label: 'Stroke (mm)', v: 75, step: 'any' }, { k: 'cyl', label: 'Cylinders', v: 4, step: '1' }], calc: function (v) { var cc = Math.PI / 4 * v.bore * v.bore * v.stroke * v.cyl / 1000; return [['Displacement', fnum(cc, 1) + ' cc'], ['Litres', fnum(cc / 1000, 2) + ' L']]; } });
  T('horsepower', 'Horsepower Calculator', 'Automotive', 'horsepower calculator, torque rpm', 'Calculate horsepower from torque and RPM.', { inputs: [{ k: 'torque', label: 'Torque (lb-ft)', v: 200, step: 'any' }, { k: 'rpm', label: 'RPM', v: 5000, step: 'any' }], calc: function (v) { return [['Horsepower', fnum(v.torque * v.rpm / 5252, 1) + ' hp']]; } });
  T('tire-size', 'Tire Size Calculator', 'Automotive', 'tire size calculator, diameter', 'Calculate overall tire diameter from its size code.', { inputs: [{ k: 'width', label: 'Width (mm)', v: 205, step: 'any' }, { k: 'ratio', label: 'Aspect ratio', v: 55, step: 'any' }, { k: 'rim', label: 'Rim (in)', v: 16, step: 'any' }], calc: function (v) { var sidewall = v.width * v.ratio / 100; var dia = v.rim * 25.4 + 2 * sidewall; return [['Diameter', fnum(dia, 1) + ' mm'], ['Diameter', fnum(dia / 25.4, 2) + ' in']]; } });
  T('0-60', 'Acceleration Time Estimator', 'Automotive', '0-60 calculator, acceleration', 'Estimate 0-100 km/h time from power-to-weight.', { inputs: [{ k: 'hp', label: 'Horsepower', v: 150, step: 'any' }, { k: 'weight', label: 'Weight (kg)', v: 1200, step: 'any' }], calc: function (v) { var t = Math.pow(v.weight / v.hp, 0.75) * 0.9; return [['Est. 0-100 km/h', fnum(t, 1) + ' s']]; } });
  T('lease', 'Car Lease Calculator', 'Automotive', 'car lease calculator, monthly lease', 'Estimate a monthly car lease payment.', { inputs: [{ k: 'price', label: 'Car price', v: 1500000, step: 'any' }, { k: 'residual', label: 'Residual value', v: 700000, step: 'any' }, { k: 'months', label: 'Lease months', v: 36, step: '1' }, { k: 'rate', label: 'Money factor (% p.a.)', v: 9, step: 'any' }], calc: function (v) { var dep = (v.price - v.residual) / v.months; var fin = (v.price + v.residual) * (v.rate / 100 / 12) / 2; return [['Monthly payment', fmoney(dep + fin)], ['Depreciation', fmoney(dep)]]; } });
  T('speed-converter-auto', 'Speed & ETA Calculator', 'Automotive', 'eta calculator, travel time, speed distance', 'Estimate travel time from distance and average speed.', { inputs: [{ k: 'dist', label: 'Distance (km)', v: 300, step: 'any' }, { k: 'speed', label: 'Avg speed (km/h)', v: 60, step: 'any' }], calc: function (v) { var h = v.dist / v.speed; return [['Travel time', Math.floor(h) + ' h ' + Math.round((h % 1) * 60) + ' m'], ['Hours', fnum(h, 2)]]; } });
  T('rpm-speed', 'RPM to Speed Calculator', 'Automotive', 'rpm to speed calculator', 'Estimate vehicle speed from engine RPM and gearing.', { inputs: [{ k: 'rpm', label: 'Engine RPM', v: 3000, step: 'any' }, { k: 'dia', label: 'Tire diameter (mm)', v: 600, step: 'any' }, { k: 'ratio', label: 'Final drive ratio', v: 3.5, step: 'any' }], calc: function (v) { var wheelRpm = v.rpm / v.ratio; var speed = wheelRpm * Math.PI * v.dia / 1000 * 60 / 1000; return [['Speed', fnum(speed, 1) + ' km/h']]; } });

