  T('discount-final', 'Discount Calculator', 'Everyday', 'discount calculator, sale price', 'Calculate the final price after a discount.', { inputs: [{ k: 'price', label: 'Original price', v: 2000, step: 'any' }, { k: 'disc', label: 'Discount (%)', v: 30, step: 'any' }], calc: function (v) { return [['Final price', fmoney(v.price * (1 - v.disc / 100))], ['You save', fmoney(v.price * v.disc / 100)]]; } });
  T('double-discount', 'Double Discount Calculator', 'Everyday', 'double discount calculator, stacked discount', 'Apply two stacked discounts to a price.', { inputs: [{ k: 'price', label: 'Price', v: 2000, step: 'any' }, { k: 'd1', label: 'First discount (%)', v: 30, step: 'any' }, { k: 'd2', label: 'Extra discount (%)', v: 10, step: 'any' }], calc: function (v) { var f = v.price * (1 - v.d1 / 100) * (1 - v.d2 / 100); return [['Final price', fmoney(f)], ['Effective discount', fnum((1 - f / v.price) * 100, 2) + ' %']]; } });
