  T('cost-per-use', 'Cost Per Use Calculator', 'Everyday', 'cost per use calculator', 'Find the cost per use of a purchase.', { inputs: [{ k: 'price', label: 'Item price', v: 5000, step: 'any' }, { k: 'uses', label: 'Expected uses', v: 100, step: 'any' }], calc: function (v) { return [['Cost per use', fmoney(v.price / v.uses)]]; } });
