  T('electricity-cost', 'Electricity Cost Calculator', 'Everyday', 'electricity cost calculator, appliance', 'Estimate the running cost of an appliance.', { inputs: [{ k: 'watts', label: 'Power (watts)', v: 1500, step: 'any' }, { k: 'hours', label: 'Hours / day', v: 5, step: 'any' }, { k: 'rate', label: 'Rate / kWh', v: 8, step: 'any' }], calc: function (v) { var daily = v.watts / 1000 * v.hours * v.rate; return [['Daily cost', fmoney(daily)], ['Monthly', fmoney(daily * 30)], ['Yearly', fmoney(daily * 365)]]; } });
