  T('pizza', 'Pizza Size Comparison', 'Everyday', 'pizza calculator, size value', 'Compare pizza value by area per rupee.', { inputs: [{ k: 'dia', label: 'Diameter (in)', v: 12, step: 'any' }, { k: 'price', label: 'Price', v: 400, step: 'any' }], calc: function (v) { var area = Math.PI * Math.pow(v.dia / 2, 2); return [['Area', fnum(area, 1) + ' in\u00B2'], ['Price per in\u00B2', fmoney(v.price / area)]]; } });
