  T('exam-target', 'Exam Target Score Calculator', 'Education', 'exam target score calculator, needed marks', 'Find the score needed on a final to reach a target.', { inputs: [{ k: 'current', label: 'Current average (%)', v: 75, step: 'any' }, { k: 'weight', label: 'Final exam weight (%)', v: 40, step: 'any' }, { k: 'target', label: 'Target overall (%)', v: 80, step: 'any' }], calc: function (v) { var needed = (v.target - v.current * (1 - v.weight / 100)) / (v.weight / 100); return [['Score needed', fnum(needed, 1) + ' %'], ['Achievable', needed <= 100 ? 'Yes' : 'Not with this weight']]; } });
