  T('ohms-power', 'Power Calculator (Electrical)', 'Science', 'electrical power calculator, watts', 'Calculate electrical power from voltage and current.', { inputs: [{ k: 'v', label: 'Voltage (V)', v: 230, step: 'any' }, { k: 'i', label: 'Current (A)', v: 5, step: 'any' }], calc: function (v) { return [['Power', fnum(v.v * v.i, 2) + ' W'], ['kW', fnum(v.v * v.i / 1000, 3)]]; } });
