  T('resistor-parallel', 'Parallel Resistance Calculator', 'Science', 'parallel resistance calculator', 'Combine resistors connected in parallel.', { inputs: [{ k: 'd', label: 'Resistances (\u03A9, comma separated)', t: 'text', v: '100, 200, 300' }], calc: function (v) { var a = LIST(v.d); var inv = a.reduce(function (s, x) { return s + 1 / x; }, 0); return [['Total resistance', fnum(1 / inv, 3) + ' \u03A9']]; } });
