  T('newtons-second-law', 'Force (F=ma) Calculator', 'Science', 'newtons second law calculator, force', 'Calculate force from mass and acceleration.', { inputs: [{ k: 'm', label: 'Mass (kg)', v: 10, step: 'any' }, { k: 'a', label: 'Acceleration (m/s\u00B2)', v: 9.8, step: 'any' }], calc: function (v) { return [['Force', fnum(v.m * v.a, 3) + ' N']]; } });
  T('momentum', 'Momentum Calculator', 'Science', 'momentum calculator', 'Calculate momentum from mass and velocity.', { inputs: [{ k: 'm', label: 'Mass (kg)', v: 5, step: 'any' }, { k: 'v', label: 'Velocity (m/s)', v: 12, step: 'any' }], calc: function (v) { return [['Momentum', fnum(v.m * v.v, 3) + ' kg\u00B7m/s']]; } });
  T('work-energy', 'Work Done Calculator', 'Science', 'work done calculator, force distance', 'Calculate work done by a force over a distance.', { inputs: [{ k: 'f', label: 'Force (N)', v: 100, step: 'any' }, { k: 'd', label: 'Distance (m)', v: 5, step: 'any' }, { k: 'ang', label: 'Angle (degrees)', v: 0, step: 'any' }], calc: function (v) { return [['Work', fnum(v.f * v.d * Math.cos(v.ang * Math.PI / 180), 3) + ' J']]; } });
  T('power-work', 'Power (Work/Time) Calculator', 'Science', 'power calculator, work time', 'Calculate power from work done over time.', { inputs: [{ k: 'w', label: 'Work (J)', v: 5000, step: 'any' }, { k: 't', label: 'Time (s)', v: 10, step: 'any' }], calc: function (v) { return [['Power', fnum(v.w / v.t, 3) + ' W']]; } });
  T('potential-energy', 'Potential Energy Calculator', 'Science', 'potential energy calculator', 'Calculate gravitational potential energy.', { inputs: [{ k: 'm', label: 'Mass (kg)', v: 10, step: 'any' }, { k: 'h', label: 'Height (m)', v: 5, step: 'any' }, { k: 'g', label: 'Gravity (m/s\u00B2)', v: 9.81, step: 'any' }], calc: function (v) { return [['Potential energy', fnum(v.m * v.g * v.h, 3) + ' J']]; } });
