  T('ideal-gas', 'Ideal Gas Law Calculator', 'Science', 'ideal gas law calculator, pv=nrt', 'Solve for pressure using the ideal gas law.', { inputs: [{ k: 'n', label: 'Moles (n)', v: 1, step: 'any' }, { k: 't', label: 'Temperature (K)', v: 300, step: 'any' }, { k: 'vv', label: 'Volume (L)', v: 22.4, step: 'any' }], calc: function (v) { var p = v.n * 0.0821 * v.t / v.vv; return [['Pressure', fnum(p, 4) + ' atm']]; } });
  T('molarity', 'Molarity Calculator', 'Science', 'molarity calculator, concentration', 'Calculate molarity of a solution.', { inputs: [{ k: 'mol', label: 'Moles of solute', v: 0.5, step: 'any' }, { k: 'l', label: 'Volume (L)', v: 2, step: 'any' }], calc: function (v) { return [['Molarity', fnum(v.mol / v.l, 4) + ' M']]; } });
