  T('half-life', 'Half-Life Calculator', 'Science', 'half life calculator, radioactive decay', 'Calculate remaining quantity after radioactive decay.', { inputs: [{ k: 'n0', label: 'Initial amount', v: 100, step: 'any' }, { k: 'hl', label: 'Half-life', v: 5, step: 'any' }, { k: 't', label: 'Elapsed time', v: 15, step: 'any' }], calc: function (v) { var n = v.n0 * Math.pow(0.5, v.t / v.hl); return [['Remaining', fnum(n, 4)], ['Decayed', fnum(v.n0 - n, 4)]]; } });
  T('speed-of-sound', 'Speed of Sound Calculator', 'Science', 'speed of sound calculator, temperature', 'Estimate the speed of sound in air at a temperature.', { inputs: [{ k: 't', label: 'Air temperature (\u00B0C)', v: 20, step: 'any' }], calc: function (v) { return [['Speed of sound', fnum(331.3 + 0.606 * v.t, 2) + ' m/s']]; } });
  T('projectile', 'Projectile Range Calculator', 'Science', 'projectile motion calculator, range', 'Calculate the range of a projectile.', { inputs: [{ k: 'v', label: 'Velocity (m/s)', v: 20, step: 'any' }, { k: 'ang', label: 'Angle (degrees)', v: 45, step: 'any' }, { k: 'g', label: 'Gravity (m/s\u00B2)', v: 9.81, step: 'any' }], calc: function (v) { var r = v.v * v.v * Math.sin(2 * v.ang * Math.PI / 180) / v.g; var h = Math.pow(v.v * Math.sin(v.ang * Math.PI / 180), 2) / (2 * v.g); return [['Range', fnum(r, 2) + ' m'], ['Max height', fnum(h, 2) + ' m']]; } });
  T('free-fall', 'Free Fall Calculator', 'Science', 'free fall calculator, drop time', 'Calculate fall time and impact speed from a height.', { inputs: [{ k: 'h', label: 'Height (m)', v: 50, step: 'any' }, { k: 'g', label: 'Gravity (m/s\u00B2)', v: 9.81, step: 'any' }], calc: function (v) { var t = Math.sqrt(2 * v.h / v.g); return [['Fall time', fnum(t, 3) + ' s'], ['Impact speed', fnum(v.g * t, 2) + ' m/s']]; } });
  T('coulombs-law', 'Coulomb\u2019s Law Calculator', 'Science', 'coulombs law calculator, electric force', 'Calculate the electrostatic force between two charges.', { inputs: [{ k: 'q1', label: 'Charge 1 (\u00B5C)', v: 5, step: 'any' }, { k: 'q2', label: 'Charge 2 (\u00B5C)', v: 3, step: 'any' }, { k: 'r', label: 'Distance (m)', v: 0.5, step: 'any' }], calc: function (v) { var f = 8.99e9 * (v.q1 * 1e-6) * (v.q2 * 1e-6) / (v.r * v.r); return [['Force', fnum(f, 4) + ' N']]; } });
  T('temperature-feels', 'Heat Index Calculator', 'Science', 'heat index calculator, feels like temperature', 'Estimate the heat index (feels-like temperature).', { inputs: [{ k: 't', label: 'Temperature (\u00B0C)', v: 32, step: 'any' }, { k: 'h', label: 'Humidity (%)', v: 70, step: 'any' }], calc: function (v) { var T = v.t * 9 / 5 + 32, R = v.h; var hi = -42.379 + 2.04901523 * T + 10.14333127 * R - 0.22475541 * T * R - 0.00683783 * T * T - 0.05481717 * R * R + 0.00122874 * T * T * R + 0.00085282 * T * R * R - 0.00000199 * T * T * R * R; return [['Feels like', fnum((hi - 32) * 5 / 9, 1) + ' \u00B0C']]; } });
  T('dew-point', 'Dew Point Calculator', 'Science', 'dew point calculator', 'Estimate the dew point from temperature and humidity.', { inputs: [{ k: 't', label: 'Temperature (\u00B0C)', v: 25, step: 'any' }, { k: 'h', label: 'Humidity (%)', v: 60, step: 'any' }], calc: function (v) { var a = 17.27, b = 237.7; var g = (a * v.t) / (b + v.t) + Math.log(v.h / 100); return [['Dew point', fnum(b * g / (a - g), 2) + ' \u00B0C']]; } });
