  T('mach', 'Mach Number Calculator', 'Science', 'mach number calculator', 'Calculate Mach number from speed and sound speed.', { inputs: [{ k: 'speed', label: 'Speed (m/s)', v: 340, step: 'any' }, { k: 'sound', label: 'Speed of sound (m/s)', v: 343, step: 'any' }], calc: function (v) { return [['Mach number', fnum(v.speed / v.sound, 3)]]; } });

  /* ===================== FUN (20) ===================== */
  T('love', 'Love Compatibility Calculator', 'Fun', 'love calculator, compatibility', 'A fun love-compatibility score from two names.', { inputs: [{ k: 'a', label: 'Your name', t: 'text', v: '' }, { k: 'b', label: 'Their name', t: 'text', v: '' }], calc: function (v) { if (!v.a || !v.b) return [['Result', 'Enter both names']]; var s = (v.a + v.b).toLowerCase().replace(/[^a-z]/g, ''); var h = 0; for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 101; return [['Love score', h + ' %'], ['Verdict', h > 70 ? 'Great match!' : h > 40 ? 'Worth a try' : 'Just friends']]; } });
  T('lucky-number', 'Lucky Number Calculator', 'Fun', 'lucky number calculator, numerology', 'Find your lucky number from your birth date.', { inputs: [{ k: 'd', label: 'Date of birth', t: 'date', v: '' }], calc: function (v) { if (!v.d) return [['Result', 'Pick a date']]; var s = v.d.replace(/[^0-9]/g, ''); function red(x) { while (x > 9) { x = String(x).split('').reduce(function (a, c) { return a + +c; }, 0); } return x; } var sum = s.split('').reduce(function (a, c) { return a + +c; }, 0); return [['Lucky number', red(sum)]]; } });
  T('name-numerology', 'Name Numerology Calculator', 'Fun', 'name numerology calculator', 'Calculate your name number using numerology.', { inputs: [{ k: 'n', label: 'Full name', t: 'text', v: '' }], calc: function (v) { if (!v.n) return [['Result', 'Enter a name']]; var s = v.n.toLowerCase().replace(/[^a-z]/g, ''); var sum = 0; for (var i = 0; i < s.length; i++) sum += (s.charCodeAt(i) - 96 - 1) % 9 + 1; while (sum > 9) sum = String(sum).split('').reduce(function (a, c) { return a + +c; }, 0); return [['Name number', sum]]; } });
  T('dice-probability', 'Dice Probability Calculator', 'Fun', 'dice probability calculator', 'Calculate the probability of rolling a target sum.', { inputs: [{ k: 'dice', label: 'Number of dice', v: 2, step: '1' }, { k: 'target', label: 'Target sum', v: 7, step: '1' }], calc: function (v) { var n = Math.round(v.dice), t = Math.round(v.target); var ways = 0, total = Math.pow(6, n); function rec(d, s) { if (d === 0) { if (s === t) ways++; return; } for (var f = 1; f <= 6; f++) rec(d - 1, s + f); } rec(n, 0); return [['Probability', fnum(ways / total * 100, 3) + ' %'], ['Ways', ways + ' / ' + total]]; } });
  T('coin-flip-odds', 'Coin Flip Probability Calculator', 'Fun', 'coin flip probability calculator', 'Probability of getting exactly k heads in n flips.', { inputs: [{ k: 'n', label: 'Number of flips', v: 10, step: '1' }, { k: 'k', label: 'Heads wanted', v: 5, step: '1' }], calc: function (v) { function f(x) { var p = 1; for (var i = 2; i <= x; i++) p *= i; return p; } var c = f(v.n) / (f(v.k) * f(v.n - v.k)); return [['Probability', fnum(c / Math.pow(2, v.n) * 100, 3) + ' %']]; } });
  T('age-in-seconds', 'Age in Seconds Calculator', 'Fun', 'age in seconds calculator', 'See your age expressed in seconds.', { inputs: [{ k: 'dob', label: 'Date of birth', t: 'date', v: '' }], calc: function (v) { if (!v.dob) return [['Result', 'Pick a date']]; var s = (new Date() - new Date(v.dob)) / 1000; return [['Seconds', fnum(s, 0)], ['Heartbeats (~72/min)', fnum(s / 60 * 72, 0)]]; } });
  T('countdown-birthday', 'Birthday Countdown Calculator', 'Fun', 'birthday countdown calculator', 'Count down the days until your next birthday.', { inputs: [{ k: 'dob', label: 'Date of birth', t: 'date', v: '' }], calc: function (v) { if (!v.dob) return [['Result', 'Pick a date']]; var b = new Date(v.dob), now = new Date(); var next = new Date(now.getFullYear(), b.getMonth(), b.getDate()); if (next < now) next.setFullYear(now.getFullYear() + 1); return [['Days to birthday', Math.ceil((next - now) / 86400000)]]; } });
