  /* ===================== REGISTER + AUTO SEO ===================== */
  function slugFor(id) { return /-(converter)$/.test(id) ? id : id + '-calculator'; }
  function relatedFor(cat, id) {
    var r = [];
    for (var i = 0; i < defs.length && r.length < 4; i++) { if (defs[i].cat === cat && defs[i].id !== id) r.push(defs[i].id); }
    return r;
  }
  function faqsFor(name, isConv) {
    var thing = isConv ? 'converter' : 'calculator';
    return [
      { q: 'How do I use the ' + name + '?', a: 'Enter your values in the fields above and the ' + name + ' updates the results instantly \u2014 no button press or sign-up needed.' },
      { q: 'Is the ' + name + ' free to use?', a: 'Yes. This ' + thing + ' is completely free, with no limits, no account and no ads getting in your way.' },
      { q: 'Does it work offline and on mobile?', a: 'Yes. Everything runs in your browser, so the ' + name + ' works on phones, tablets and desktops, and keeps working even without an internet connection.' }
    ];
  }

  defs.forEach(function (d) {
    var isConv = /-(converter)$/.test(d.id);
    var icon = IC[d.cat] || '\uD83E\uDDEE';
    if (root.CS && root.CS.Calc && typeof root.CS.Calc.register === 'function') {
      root.CS.Calc.register({ id: d.id, name: d.name, category: d.cat, icon: icon, description: d.blurb, render: simple(d.def) });
    }
    if (!SEO.TOOLS[d.id]) {
      var options = (d.def.inputs || []).map(function (f) { return f.label; });
      SEO.TOOLS[d.id] = {
        slug: slugFor(d.id),
        cat: d.cat,
        icon: icon,
        name: d.name,
        title: d.name + ' \u2013 Free Online ' + (isConv ? 'Converter' : 'Calculator'),
        desc: d.blurb,
        keywords: d.kw,
        intro: d.blurb + ' This free tool works instantly in your browser on any device, with no sign-up required.',
        options: options,
        faqs: faqsFor(d.name, isConv),
        related: relatedFor(d.cat, d.id)
      };
      if (SEO.ORDER.indexOf(d.id) === -1) SEO.ORDER.push(d.id);
    }
  });

  if (typeof module !== 'undefined' && module.exports) { module.exports = SEO; }
